-- Generated by scripts/generate-seed.mjs from lib/mockData.ts — do not hand-edit.
-- Re-run the generator after changing the catalogue in mockData.ts; game ids are
-- deterministic (UUIDv5 of the catalogue key), so re-running this file is an upsert,
-- not a duplicate insert.

-- 67 games (1 non-selectable reference-data anchors)
-- resolve base_game_id -> games(id) is already correct above since anchors are inserted
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  mark = excluded.mark,
  logo_url = excluded.logo_url,
  steam_app_id = excluded.steam_app_id,
  platforms = excluded.platforms,
  is_mobile = excluded.is_mobile,
  has_team_feature = excluded.has_team_feature,
  base_game_id = excluded.base_game_id,
  version_label = excluded.version_label,
  version_date = excluded.version_date,
  is_selectable = excluded.is_selectable;

-- 65 game_reference_data rows (one per base game)
on conflict (game_id) do update set
  maps = excluded.maps,
  weapons = excluded.weapons,
  roles = excluded.roles;
